     [R(OSTEP, "Address Spaces, Segmentation, Free-Space Management, Paging 장"), R(SILBER_OS, "Main Memory 장"), G2R("computer-architecture", 8, "컴퓨터 구조 8단원 가상 메모리와 TLB")],
