     [R(OSTEP, "I/O Devices, Hard Disk Drives 장"), R(SILBER_OS, "Mass-Storage Structure, I/O Systems 장"), G2R("computer-architecture", 11, "컴퓨터 구조 11단원 저장 장치와 RAID")],
