def verify():
    def fifo(r, n):
        f, c = [], 0
        for x in r:
            if x not in f:
                c += 1
                if len(f) == n: f.pop(0)
                f.append(x)
        return c
    def lru(r, n):
        f, c = [], 0
        for x in r:
            if x in f: f.remove(x); f.append(x)
            else:
                c += 1
                if len(f) == n: f.pop(0)
                f.append(x)
        return c
    assert fifo(REF, 3) == 9 and lru(REF, 3) == 8
    assert (0 + 24 + 27) / 3 == 17 and (0 + 3 + 6) / 3 == 3 and abs((6 + 4 + 7) / 3 - 5.667) < 0.001
    assert 4 * 2 + 1 == 9 and divmod(2500, 1024) == (2, 452) and 1024 * 4 == 4096
    q, h = [98, 183, 37, 122, 14, 124, 65, 67], 53
    assert sum(abs(a - b) for a, b in zip([h] + q, q)) == 640


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
